#!/usr/bin/env node
/**
 * Generates src/known-routes.ts from the shared route catalog
 * (src/seo/routeCatalog.ts — same source as prerender, app-page metadata
 * and scripts/audit-routes.mjs) and fails the deploy when:
 *   - an App.tsx route has no resolver / is not matched by the known set,
 *   - a prerender catalog route (getAllRoutes) would be 404'd,
 *   - a sitemap URL would be 404'd,
 *   - an ALL_REDIRECTS target is unknown (a 301 into a 404).
 * The Worker no longer embeds prerendered HTML; the origin serves every page.
 */
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath, pathToFileURL } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "../..");
const OUT_DIR = path.resolve(__dirname, ".catalog");
const OUT = path.resolve(__dirname, "src/known-routes.ts");

fs.rmSync(OUT_DIR, { recursive: true, force: true });
const r = spawnSync(
  "npx",
  ["vite", "build", "--ssr", "workers/route-server/catalog-entry.ts", "--outDir", OUT_DIR, "--emptyOutDir", "--logLevel", "warn"],
  { cwd: REPO_ROOT, stdio: "inherit" },
);
if (r.status !== 0) { console.error("[build-bundle] catalog bundle failed"); process.exit(1); }

const mod = await import(pathToFileURL(path.join(OUT_DIR, "catalog-entry.js")).href);
const data = mod.buildKnownRouteData(); // throws on an App.tsx route without a resolver
const isKnown = mod.createMatcher(data);
const errors = [];

// 1. Every concrete App.tsx route must be known (redirect-only routes included).
for (const { path: p, element } of mod.parseAppRoutes()) {
  if (/^<NotFound\b/.test(element) || p === "*" || p === "/" || p.includes("*")) continue;
  const rest = p.replace(/^\/:lang(?=\/|$)/, "");
  if (rest.includes(":")) continue;
  const concrete = p.startsWith("/:lang") ? data.locales.map((l) => `/${l}${rest}`) : [p];
  for (const c of concrete) if (!isKnown(c)) errors.push(`App.tsx route not known: ${c}`);
}
// 2. Every prerender catalog route.
for (const p of mod.getAllRoutes()) if (p !== "/" && !isKnown(p)) errors.push(`catalog route not known: ${p}`);
// 3. Sitemap.
const sitemap = path.resolve(REPO_ROOT, "public/sitemap.xml");
if (fs.existsSync(sitemap)) {
  for (const m of fs.readFileSync(sitemap, "utf8").matchAll(/<loc>https:\/\/(?:www\.)?woolet\.co([^<]*)<\/loc>/g)) {
    const p = m[1] || "/";
    if (p !== "/" && !isKnown(p)) errors.push(`sitemap URL not known: ${p}`);
  }
}
// 4. Redirect targets (src/seo/legacyRedirects.ts ALL_REDIRECTS - the Worker
//    resolves redirects from the same module as the router and prerender).
for (const [src, dst] of Object.entries(mod.ALL_REDIRECTS)) {
  if (/^https?:/.test(dst)) continue;
  if (!isKnown(dst.split(/[?#]/)[0])) errors.push(`redirect ${src} -> unknown ${dst}`);
}

if (errors.length) {
  console.error(`[build-bundle] FAILED — ${errors.length} problem(s):\n  ${errors.join("\n  ")}`);
  process.exit(1);
}

fs.writeFileSync(OUT, `// AUTO-GENERATED by build-bundle.mjs from src/seo/routeCatalog.ts — DO NOT EDIT.
import type { KnownRouteData } from "./routes";
export const KNOWN_ROUTES: KnownRouteData = ${JSON.stringify(data)};
`);
fs.rmSync(OUT_DIR, { recursive: true, force: true });
console.log(`[build-bundle] wrote ${OUT}: ${data.exact.length} exact routes, ${data.families.length} families`);
for (const f of data.families) {
  if ("prefix" in f) console.log(`  • ${f.prefix}*`);
  else console.log(`  • ${f.pattern} (${Array.isArray(f.slugs) ? f.slugs.length : Object.values(f.slugs).flat().length} slugs)`);
}
